const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const nycPoint = ee.Geometry.Point([-74.0060, 40.7128]);
    const areaOfInterest = nycPoint.buffer(15000); // 15km buffer to cover NYC
    const dateStart = '2002-08-14';
    const dateEnd = '2002-08-15';

    // 2. Data Acquisition & Pre-processing
    // Function to mask clouds, shadow, and water for Landsat 5 C2 L2
    function maskL5sr(image) {
        // Bits 3 (cloud shadow), 5 (cloud), and 2 (water) are the flags to check.
        const qa = image.select('QA_PIXEL');
        const cloudShadowBitMask = (1 << 3);
        const cloudBitMask = (1 << 5);
        const waterBitMask = (1 << 2);
        const mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
            .and(qa.bitwiseAnd(cloudBitMask).eq(0))
            .and(qa.bitwiseAnd(waterBitMask).eq(0)); // Mask out water
        return image.updateMask(mask);
    }

    // Function to calculate NDVI and ST
    function calculateIndices(image) {
        const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
        // Apply scaling factors for ST. Formula: (DN * 0.00341802 + 149.0) - 273.15
        const stCelsius = image.select('ST_B6').multiply(0.00341802).add(149.0).subtract(273.15).rename('ST_C');
        return image.addBands(ndvi).addBands(stCelsius);
    }

    const l5collection = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
        .filterBounds(areaOfInterest)
        .filterDate(dateStart, dateEnd);

    const collectionSize = l5collection.size().getInfo();
    if (collectionSize === 0) {
        console.log("Image collection is empty for the specified date and location.");
        console.log("A: No");
        return;
    }

    const image = l5collection.map(maskL5sr).map(calculateIndices).mosaic();

    // 3. Define vegetation density classes
    const highVegMask = image.select('NDVI').gte(0.4);
    const lowVegMask = image.select('NDVI').lt(0.2).and(image.select('NDVI').gte(0)); // Low but not bare

    const imageHighVeg = image.updateMask(highVegMask);
    const imageLowVeg = image.updateMask(lowVegMask);

    const scale = 1000;

    // 4. Calculate statistics
    const statsHighVeg = imageHighVeg.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: areaOfInterest,
        scale: scale,
        maxPixels: 1e9
    });

    const statsLowVeg = imageLowVeg.reduceRegion({
        reducer: ee.Reducer.mean().combine({
            reducer2: ee.Reducer.count(),
            sharedInputs: true
        }),
        geometry: areaOfInterest,
        scale: scale,
        maxPixels: 1e9
    });

    // Use evaluate to avoid blocking and potential timeouts on getInfo()
    ee.Dictionary(statsHighVeg).evaluate((highVegResult) => {
        ee.Dictionary(statsLowVeg).evaluate((lowVegResult) => {
            const highVegTemp = highVegResult ? highVegResult.ST_C : null;
            const highVegPixels = highVegResult ? highVegResult.ST_C_count : 0;
            const lowVegTemp = lowVegResult ? lowVegResult.ST_C : null;
            const lowVegPixels = lowVegResult ? lowVegResult.ST_C_count : 0;

            console.log(`High Vegetation (NDVI>=0.4) Pixels: ${highVegPixels}`);
            console.log(`Low Vegetation (0<=NDVI<0.2) Pixels: ${lowVegPixels}`);

            if (highVegPixels === 0 || lowVegPixels === 0) {
                console.log("No valid pixels in one or both vegetation classes after masking.");
                console.log("C2");
                return;
            }

            if (highVegTemp === null || lowVegTemp === null) {
                console.log("Calculation failed, could not retrieve temperature values.");
                console.log("C3");
                return;
            }

            console.log(`Avg Temp in High Vegetation Areas: ${highVegTemp.toFixed(2)} C`);
            console.log(`Avg Temp in Low Vegetation Areas: ${lowVegTemp.toFixed(2)} C`);

            if (highVegTemp < lowVegTemp) {
                console.log("Evidence: Temp in high vegetation areas is lower than in low vegetation areas.");
                console.log("A");
            } else {
                console.log("Evidence: Temp in high vegetation areas is NOT lower than in low vegetation areas.");
                console.log("B");
            }
        });
    });
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log("D");
});
